package openshell

import (
	"strings"

	"github.com/michael-freling/claude-forge/internal/forge/layout"
)

// Memory returns the instructions written to the sandbox's ~/.claude/CLAUDE.md.
// They tell the agent what it cannot observe about its environment: that it is
// in a sandbox with its own workspace, which network access it has, and how
// GitHub credentials work.
func Memory(githubToken bool, pushRepos []string) string {
	var b strings.Builder
	b.WriteString(`# OpenShell sandbox (claude-forge)

<!-- Generated by claude-forge on every connect; edits here are overwritten.
     Put your own instructions in ~/.claude/CLAUDE.md or ~/.claude/rules/ on
     the host: they are copied into every sandbox. -->

## You are running in a sandbox, not on the host

This session runs in an OpenShell sandbox, not on the user's machine. Its
filesystem, installed packages, processes and network are its own. Nothing on
the user's machine is mounted here, so never assume a file, tool or service
from their machine is reachable.

## Work in ` + "`" + layout.Workspace + "`" + `

` + "`" + layout.Workspace + "`" + ` is this sandbox's persistent workspace: it survives
reconnects and stop/start, until the sandbox is deleted. Clone every repository
you need into it, one directory each, for example:

    git clone https://github.com/<owner>/<repo>.git ` + layout.Workspace + `/<repo>

Several repositories can be cloned and worked on side by side. The user sees
your work through what you push (branches, pull requests), not through files on
their machine, so push finished work and say which branch it is on. When you
name a file to the user, write it relative to its repository root.

## Network access is an allowlist

Only some hosts are reachable: Anthropic, GitHub, PyPI, npm, AWS, GCP, Go
modules and a few documentation sites. Other hosts fail with a connection or
policy error; that is the sandbox policy, not an outage. Say which host you
needed instead of retrying. Docker is not available.
`)

	b.WriteString("\n## GitHub\n\n")
	if !githubToken {
		b.WriteString(`No GitHub credential is configured, so only public repositories can be
cloned, and pushing or GitHub API writes fail.
`)
		return b.String()
	}

	b.WriteString("`$GITHUB_TOKEN` holds a placeholder for the user's GitHub token; the sandbox\n" +
		"replaces it with the real token only on requests to GitHub. git over HTTPS is\n" +
		"already configured to use it, so clone, fetch and push work for any repository\n" +
		"the token can access. There is no `gh` CLI: call the REST API with curl, e.g.\n\n" +
		"    curl -H \"Authorization: Bearer $GITHUB_TOKEN\" https://api.github.com/repos/<owner>/<repo>/pulls\n\n" +
		"SSH remotes (`git@github.com:...`) have no key here; use HTTPS URLs.\n")
	if len(pushRepos) > 0 {
		b.WriteString("\nPushing and GitHub API writes are allowed only for these repositories:\n\n")
		for _, r := range pushRepos {
			b.WriteString("- " + r + "\n")
		}
		b.WriteString("\nReading and cloning any repository is still allowed. GraphQL is read-only.\n")
	}
	return b.String()
}
